'Reembolsos'=>['¿Qué situaciones habilitan un reembolso?','¿Se devuelve también el envío?','¿Qué ocurre si el pedido ya fue despachado?','¿Cómo se tratan productos dañados?','¿Cómo se revierte la comisión del influencer?','¿Los reembolsos parciales están permitidos?'],
